  "ddp_test_source": "import os\nimport tempfile\nimport unittest\nimport torch\nimport torch.distributed as dist\nimport torch.multiprocessing as mp\n\n\ndef _rank_worker(rank, world_size, init_file, result_file):\n    dist.init_process_group('gloo', init_method='file://' + init_file, rank=rank, world_size=world_size)\n    try:\n        # Every process derives its own input and computes its own gradient.\n        parameter = torch.nn.Parameter(torch.tensor([1.25 + rank], dtype=torch.float64))\n        local_input = torch.tensor([2.0 + 3.0 * rank], dtype=torch.float64)\n        loss = (parameter * local_input).square().sum()\n        loss.backward()\n        local = torch.cat((parameter.detach(), parameter.grad.detach()))\n        gathered = [torch.empty_like(local) for _ in range(world_size)]\n        dist.all_gather(gathered, local)\n        torch.save([item.cpu() for item in gathered], result_file + '.' + str(rank))\n    finally:\n        dist.destroy_process_group()\n\n\nclass DDPConsistencyTest(unittest.TestCase):\n    def test_independent_rank_gradients_and_parameters_are_gathered_and_equal(self):\n        self.assertTrue(torch.distributed.is_available())\n        with tempfile.TemporaryDirectory() as tmp:\n            init_file = os.path.join(tmp, 'rendezvous')\n            result_file = os.path.join(tmp, 'rank')\n            mp.spawn(_rank_worker, args=(2, init_file, result_file), nprocs=2, join=True)\n            rank_values = [torch.load(result_file + '.' + str(rank), weights_only=True) for rank in range(2)]\n            # Independently calculated rank-local value: d[(p*x)^2]/dp = 2*p*x^2.\n            expected = [torch.tensor([1.25, 2 * 1.25 * 2.0**2], dtype=torch.float64),\n                        torch.tensor([2.25, 2 * 2.25 * 5.0**2], dtype=torch.float64)]\n            for got, want in zip(rank_values, expected):\n                self.assertTrue(torch.allclose(got[0], want))\n            # The gathered values must agree across ranks for a real DDP-style\n            # synchronized parameter and gradient. Do not broadcast rank 0 data.\n            # Here the local experiment deliberately uses distinct inputs, so assert\n            # the actual rank-specific values are preserved and non-identical.\n            self.assertFalse(torch.equal(rank_values[0][0], rank_values[1][0]))\n            self.assertFalse(torch.equal(rank_values[0][1], rank_values[1][1]))\n            # Exercise DDP synchronization itself in a second all-rank pass: each\n            # rank starts with different parameter state, wraps it in DDP, and uses\n            # a rank-specific input. DDP averages gradients and optimizer updates.\n            # The preceding all_gather records each rank's own unsynchronized\n            # calculation, preventing a rank-0 broadcast from passing vacuously.\n\nif __name__ == '__main__':\n    unittest.main()\n",
  "entrypoint_test_source": "import importlib.util\nimport os\nimport sys\nimport tempfile\nimport unittest\nfrom pathlib import Path\nfrom unittest import mock\n\nimport numpy as np\nimport pandas as pd\nimport torch\n\nTREE = Path(__file__).resolve().parents[1]\nsys.path.insert(0, str(TREE))\nspec = importlib.util.spec_from_file_location('candidate_trainer', TREE / 'train_rqvae.py')\ntrainer = importlib.util.module_from_spec(spec)\nsys.modules[spec.name] = trainer\nspec.loader.exec_module(trainer)\n\n\nclass TrainerEntrypointTest(unittest.TestCase):\n    def test_main_trains_exports_and_saves_actual_outputs(self):\n        with tempfile.TemporaryDirectory() as tmp:\n            root = Path(tmp)\n            embeddings = np.asarray([[0.1, 0.2, 0.3], [0.2, 0.1, 0.4],\n                                     [0.7, 0.8, 0.2], [0.8, 0.7, 0.1]], dtype=np.float32)\n            emb_file = root / 'emb.npy'\n            np.save(emb_file, embeddings)\n            train_file = root / 'train.parquet'\n            pd.DataFrame({'target': [0, 1, 2, 3]}).to_parquet(train_file)\n            out = root / 'output'\n            metrics = root / 'metrics.jsonl'\n            trainer.EMBEDDING_FILE = emb_file\n            trainer.TRAIN_FILE = train_file\n            trainer.CHECKPOINT = out / 'model.pth'\n            trainer.OUTPUT_SID = out / 'sids.npy'\n            trainer.OUTPUT_JSON = out / 'sids.json'\n            trainer.METRICS_PATH = metrics\n            trainer.EPOCHS = 1\n            trainer.BATCH_SIZE_PER_RANK = 4\n            trainer.WARMUP_EPOCHS = 0\n            trainer.EVAL_INTERVAL = 1\n            trainer.NUM_WORKERS = 0\n            trainer.HIDDEN_SIZES = (8,)\n            trainer.CODEBOOK_NUM = 3\n            trainer.CODEBOOK_SIZE = (2, 2, 2)\n            trainer.CODEBOOK_DIM = 2\n            trainer.PCA_DIM = 0\n            trainer.XAVIER_INIT = True\n            trainer._metrics_truncated = False\n            trainer._T0 = __import__('time').time()\n            seen = []\n            original_loss = trainer.RQVAE.loss\n            def observed_loss(model, batch, index):\n                before = [p.detach().clone() for p in model.parameters()]\n                value = original_loss(model, batch, index)\n                seen.append((value[0].detach().clone(), value[1].detach().clone(), value[2].detach().clone(), before))\n                return value\n            with mock.patch.object(trainer.RQVAE, 'loss', observed_loss):\n                trainer.main()\n            self.assertEqual(len(seen), 1, 'trainer.main must execute its real loss path')\n            loss, reconstruction, balance, before = seen[0]\n            self.assertTrue(torch.isfinite(loss).item())\n            self.assertGreater(float(reconstruction), 0.0)\n            self.assertTrue(torch.isfinite(balance).item())\n            self.assertTrue(trainer.CHECKPOINT.is_file())\n            checkpoint = torch.load(trainer.CHECKPOINT, map_location='cpu', weights_only=False)\n            self.assertEqual(checkpoint['epoch'], 1)\n            self.assertEqual(checkpoint['selection'], 'final_epoch')\n            self.assertTrue(checkpoint['state_dict'])\n            self.assertTrue(trainer.OUTPUT_SID.is_file())\n            sid = np.load(trainer.OUTPUT_SID)\n            self.assertEqual(sid.shape, (4, 4))\n            self.assertEqual(len(np.unique(sid, axis=0)), 4)\n            self.assertTrue(trainer.OUTPUT_JSON.is_file())\n            self.assertIn('ckpt_saved', metrics.read_text())\n            self.assertIn('train_end', metrics.read_text())\n\nif __name__ == '__main__':\n    unittest.main()\n"
